// Marlin V4 compact NNUE inference. Weights are generated by training/train_nnue.py.
let network = null;

export async function loadNnueWeights(url = "./nnue/marlin-v4.nnue.json") {
  const response = await fetch(url, { cache: "no-cache" });
  if (!response.ok) throw new Error("NNUE weights unavailable: " + response.status);
  const candidate = await response.json();
  if (candidate.format !== "MARLIN_NNUE_V1" ||
      candidate.feature_encoding !== "stm-relative-piece-square-v1" ||
      candidate.architecture !== "768x128x32x1") {
    throw new Error("Incompatible MARLIN NNUE weights");
  }
  network = candidate.weights;
  return candidate.training || {};
}

export function hasNnueWeights() { return network !== null; }

export function evaluateNnue(game) {
  if (!network) return null;
  const board = game.board();
  const side = game.turn();
  const active = [];
  const typeIndex = { p:0, n:1, b:2, r:3, q:4, k:5 };
  for (let r=0; r<8; r++) for (let c=0; c<8; c++) {
    const p = board[r][c];
    if (!p) continue;
    const relativeColour = p.color === side ? 0 : 1;
    const square = (7-r)*8+c;
    active.push(relativeColour*384 + typeIndex[p.type]*64 + square);
  }
  const w = network;
  const h1 = w.fc1_b.slice();
  for (const feature of active) {
    const row = w.fc1_w[feature];
    for (let j=0; j<h1.length; j++) h1[j] += row[j];
  }
  for (let j=0; j<h1.length; j++) h1[j] = Math.max(0, h1[j]);
  const h2 = w.fc2_b.slice();
  for (let i=0; i<h1.length; i++) {
    const v = h1[i]; if (!v) continue;
    const row = w.fc2_w[i];
    for (let j=0; j<h2.length; j++) h2[j] += v*row[j];
  }
  let output = w.out_b;
  for (let i=0; i<h2.length; i++) output += Math.max(0,h2[i])*w.out_w[i];
  return Math.round(output * 800);
}
